import {create,step,close,restore,choices,costs,MODEL} from './model.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),KEY='company-life-save-v1';let config,s,draft,selected='keep',saveError='',brokenRaw='',busy=false;
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Math.round(v).toLocaleString('ja-JP'),money=v=>num(v)+'万円',period=q=>`${Math.floor((q-1)/4)+1}年目・第${(q-1)%4+1}四半期`,newSeed=()=>crypto.getRandomValues(new Uint32Array(1))[0];
const header=()=>`<header><div class="brand"><span class="brand-mark">会</span><div><strong>会社の一生</strong><small>A SMALL COMPANY, AN UNTOLD STORY</small></div></div><nav>${s?'<button data-do="history">会社の記録</button>':''}<button data-do="data">データと仮定</button><span class="demo">DEMO / 5 YEARS</span></nav></header>`;
const footer=()=>`<div class="footer-note"><span>統計を参考にする設計の、架空の経営シミュレーション。現在の数値はすべてゲーム用の仮置きです。</span><span>会社の一生　/　DEMO 0.1</span></div>`;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(s));saveError='';}catch(e){saveError='保存できませんでした。この画面では続けられますが、閉じる前に記録を書き出してください。';}}
function welcome(){draft ||= create(newSeed(),'こもれびソフト',config);app.innerHTML=header()+`<main class="page">${brokenRaw?`<div class="toast">${esc(saveError)} <button class="text-button" data-do="export-broken">元の記録を書き出す</button></div>`:''}<div class="welcome"><section class="intro"><div class="eyebrow">Every company has a story</div><h1>小さな会社の、<br>まだ知らない物語。</h1><p>はじめての受注。頼もしい仲間。思いがけない向かい風。<br>あなたの選択と、少しの偶然が、一社の歴史になる。<br>小さな開発会社の、最初の5年間を歩いてみませんか。</p></section><div class="hero-art"><img src="../assets/studio.png" alt="木の机と緑に囲まれた、小さな開発会社のミニチュア事務所"><span class="art-note">ここから、ひとつの会社が始まる。</span></div></div><section class="start-box"><div class="field"><label for="company">あなたの会社の名前</label><input id="company" maxlength="24" value="${esc(draft.name)}" autocomplete="off"><div class="start-actions"><button class="primary" data-do="start">この会社をはじめる <span class="arrow">→</span></button><button class="text-button" data-do="reroll">↻ 別の創業条件</button></div></div><div><div class="eyebrow">The beginning / 創業の条件</div><div class="conditions"><div><small>手元資金</small><strong>${num(draft.cash)}</strong><span> 万円</span></div><div><small>あなたと、仲間</small><strong>${draft.staff+1}</strong><span> 人</span></div><div><small>創業者の開発経験</small><strong>${draft.experience}</strong><span> 年</span></div></div><p style="font-size:11px;color:var(--muted)">受託ソフトウェア開発 / 取引先2社 / 創業借入300万円（手元資金に含む）<br>景気は「${['不調','平常','好調'][draft.macro]}」。1回の選択で3か月が進みます。目安10〜15分。</p></div></section>${footer()}</main>`;}
function render(){if(!s){welcome();return;}if(s.ended){result();return;}const q=s.q+1,available=choices(s);if(!available.some(c=>c.id===selected))selected='keep';const ar=s.receivables.reduce((a,r)=>a+r.amount,0),crisis=s.cash<costs(s)*1.4;app.innerHTML=header()+`<main class="page reduced-move">${saveError?`<div class="toast">${esc(saveError)} <button data-do="export" class="text-button">記録を書き出す</button></div>`:''}<div class="masthead"><div><div class="eyebrow">Software studio / 受託開発</div><h1>${esc(s.name)}</h1></div><div class="quarter"><strong>${Math.floor(s.q/4)+1}年目 <span style="font-size:13px">${['春','夏','秋','冬'][s.q%4]}</span></strong><small>第${s.q%4+1}四半期 / 創業から${s.q*3}か月</small><div class="progress" aria-label="20期中${s.q}期を完了">${Array.from({length:20},(_,i)=>`<i class="${i<s.q?'done':''}"></i>`).join('')}</div></div></div><div class="game-grid"><div><div class="office"><img src="../assets/studio.png" alt="会社の拠点となる小さな事務所のイメージ"><div class="scene-top"><span class="scene-chip">${s.staff+1<=3?'小さな事務所':s.staff+1<=5?'仲間が集まる事務所':'にぎやかな開発室'}</span><span class="scene-chip weather">${['☁ 景気は不調','◌ 景気は平常','☀ 景気は好調'][s.macro]}</span></div><div class="scene-bottom"><div><div class="crew" aria-hidden="true">${Array.from({length:Math.min(s.staff+1,12)},()=>'<i class="person"></i>').join('')}</div><div class="team-info">あなた ＋ ${s.staff}人の仲間</div></div><div class="scene-caption">${s.fatigue>60?'少し、休む時間も必要かもしれない。':s.skill>1.1?'あの日の工夫が、今日を支えている。':s.clients.length>3?'新しい出会いが、会社を広げていく。':'ひとつずつ、信頼を積み重ねて。'}</div></div></div><div class="metrics"><div class="metric"><label>手元資金</label><strong class="${crisis?'negative':''}">${num(s.cash)}<span>万円</span></strong><small>${s.q?`${s.last.deltaCash>=0?'＋':''}${num(s.last.deltaCash)}万円 / 前期比`:'ここから始まる'}</small></div><div class="metric"><label>前期の売上</label><strong>${s.q?num(s.last.revenue):'—'}<span>万円</span></strong><small>入金待ち ${num(ar)}万円</small></div><div class="metric"><label>前期の利益</label><strong class="${s.last.profit<0?'negative':''}">${s.q?num(s.last.profit):'—'}<span>万円</span></strong><small>費用と利息を控除</small></div><div class="metric"><label>仕事の充足率</label><strong>${s.q?num(s.last.load*100):'—'}<span>%</span></strong><small>${s.last.load>1?'能力より仕事が多い':s.q?'処理能力に対する仕事量':'初回の受注を待つ'}</small></div></div>${crisis?'<div class="warning">資金に余裕がありません。次の支払いに備えて、調達・縮小の選択肢を確認してください。</div>':''}<section aria-live="polite"><div class="section-heading"><h2>${s.q?'この四半期の出来事':'創業の日'}</h2><small>${s.q?period(s.q):'PROLOGUE'}</small></div><div class="events">${s.last.events.slice(0,3).map(eventView).join('')}</div>${s.last.events.length>3?`<details class="event-more"><summary>ほか${s.last.events.length-3}件の出来事</summary>${s.last.events.slice(3).map(eventView).join('')}</details>`:''}</section><details><summary>資金の内訳と、会社の状態を見る　＋</summary>${ledger()}${clients()}<p style="font-size:10px;color:var(--muted)">信頼 ${num(s.trust)}/100 · 疲労 ${num(s.fatigue)}/100 · 改善倍率 ${s.skill.toFixed(2)} · 待ち仕事 ${money(s.backlog)}</p></details></div><aside class="sidebar"><div class="eyebrow">Your next chapter / ${String(q).padStart(2,'0')}</div><h2>${crisis?'次の季節へ、つなぐために。':s.last.load>1.1?'忙しさの、その先へ。':'この季節、何を大切にする？'}</h2><p class="help">${crisis?'守るための決断も、会社の大切な一ページです。':s.last.load>1.1?'仕事は増えています。仲間を迎えるか、今の体制で向き合うか。':'ひとつの方針を選んで、次の3か月へ。選択と偶然が、会社の明日をつくります。'}</p><div class="choices" role="group" aria-label="経営方針">${available.map(c=>`<button class="choice ${selected===c.id?'selected':''}" aria-pressed="${selected===c.id}" data-choice="${c.id}"><div class="choice-top"><span>${c.tag}</span><span>${c.cost?`支出 ${c.cost}万円`:'追加支出なし'}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.desc)}</p><p class="effect">${esc(c.effect)}</p></button>`).join('')}</div><button class="primary next" data-do="next">この方針で、3か月を進める <span class="arrow">→</span></button><div class="save-state">${saveError?'△ 未保存':'◌ 四半期ごとに自動保存'}　・　あと${20-s.q}四半期</div><div class="minor-row"><button class="text-button" data-do="history">↗ これまでの歩み</button><button class="text-button" data-do="close-company">会社を閉じる</button></div></aside></div>${footer()}</main>`;}
function eventView(e){return `<article class="event ${e.kind}"><span class="event-icon">${e.kind==='risk'?'!':e.kind==='turning'?'✧':e.kind==='world'?'○':'·'}</span><div><h3>${esc(e.title)}</h3><p>${esc(e.text)}</p></div></article>`;}
function ledger(){const l=s.last;return `<table class="ledger"><tbody>${s.q?[[`前期首の現金`,money(l.startCash)],['売上（納品した仕事）',money(l.revenue)],['費用（給与・施策など）',`−${money(l.operating)}`],['利息',`−${money(l.interest)}`],['利益 = 売上 − 費用 − 利息',money(l.profit)],['実際に回収した現金',`＋${money(l.collections)}`],['新規借入',`＋${money(l.borrow)}`],['元本返済（費用に含めない）',`−${money(l.repay)}`],['期末現金 = 期首 + 回収 + 借入 − 費用 − 利息 − 返済',money(s.cash)]].map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join(''):''}<tr><td>借入残高</td><td>${money(s.debt)}</td></tr><tr><td>売掛金（次期回収予定）</td><td>${money(s.receivables.reduce((a,r)=>a+r.amount,0))}</td></tr><tr><td>次期の通常費用目安（給与・役員報酬・固定費）</td><td>${money(costs(s))}</td></tr><tr><td>従業者数（創業者を含む）</td><td>${s.staff+1}人</td></tr></tbody></table>`;}
function clients(){const total=s.clients.reduce((a,c)=>a+c.value,0);return `<div class="section-heading"><h2>取引先とのつながり</h2><small>基準受注額に占める比率</small></div>${s.clients.map(c=>`<div class="client-row"><span>${esc(c.name)}</span><div class="bar"><b style="width:${c.value/total*100}%"></b></div><span>${num(c.value/total*100)}%</span></div>`).join('')}`;}
function chart(metric='cash',label='手元資金 / 万円'){const vals=[metric==='cash'?s.initial.cash:metric==='staff'?s.initial.staff+1:0,...s.history.map(h=>metric==='staff'?h.staff+1:h[metric])],min=Math.min(0,...vals),max=Math.max(1,...vals),y=v=>135-(v-min)/(max-min)*110,x=i=>45+i/Math.max(1,vals.length-1)*485;return `<div class="chart-label"><span>${label}</span><span>創業 → ${s.q}期目</span></div><svg class="chart" viewBox="0 0 550 160" role="img" aria-label="${label}の推移。創業時${num(vals[0])}、現在${num(vals.at(-1))}"><line x1="45" y1="25" x2="530" y2="25"/><line x1="45" y1="135" x2="530" y2="135"/><text x="0" y="29">${num(max)}</text><text x="0" y="139">${num(min)}</text><polyline points="${vals.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}"/>${vals.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="2.7"><title>${i}期: ${num(v)}</title></circle>`).join('')}<text x="45" y="157">創業</text><text x="490" y="157">${s.q}期</text></svg>`;}
function timeline(curated=false){let rows=s.history;if(curated&&rows.length>7){const significant=rows.filter(h=>h.events.some(e=>e.kind==='turning'||e.kind==='risk'));const map=new Map([rows[0],...significant.slice(0,5),rows.at(-1)].map(h=>[h.q,h]));rows=[...map.values()].sort((a,b)=>a.q-b.q);}return `<ol class="history-list"><li><small>PROLOGUE / 創業</small><h3>${s.initial.staff+1}人と、${money(s.initial.cash)}から。</h3><p>開発経験${s.initial.experience}年。取引先2社との関係から始まった。</p></li>${rows.map(h=>`<li><small>${period(h.q)} / ${h.action}</small>${(curated?[h.events.find(e=>e.kind==='turning'||e.kind==='risk')||h.events[0]]:h.events).map(e=>`<h3>${esc(e.title)}</h3><p>${esc(e.text)}</p>`).join('')}<p>資金 ${money(h.cash)} · 売上 ${money(h.revenue)} · ${h.staff+1}人</p></li>`).join('')}</ol>`;}
function result(){const outcome=s.ended==='five-years'?(s.staff>s.initial.staff?'仲間と育てた、5年間。':s.cash>s.initial.cash?'小さな歩幅で、遠くまで。':'続けることも、ひとつの答え。'):s.ended==='closed'?'ここで、ひとつの区切り。':'灯りを消しても、歩みは残る。';app.innerHTML=header()+`<main class="page result reduced-move"><div class="result-top"><div class="eyebrow">${s.ended==='five-years'?'To be continued':'A chapter to remember'}</div><h1>${outcome}</h1><p>${s.ended==='five-years'?'創業から5年。これは終わりではなく、ここまでの記録。':s.ended==='closed'?'あなたの判断で、会社の経営を終えました。':'四半期末の支払いに必要な資金を確保できず、継続不能となりました。'}<br>${s.ended==='insolvent'?'ゲーム上の終了であり、法的な倒産手続を表すものではありません。':'選んだことと、思いがけず起きたこと。その両方が、この会社をつくりました。'}</p></div><div class="result-body"><div><div class="eyebrow">The company you built</div><h2 class="result-name" style="margin-top:12px">${esc(s.name)}</h2><img class="result-image" src="../assets/studio.png" alt="思い出の事務所"><div class="result-stats"><div><small>積み重ねた時間</small><strong>${s.q*3}か月</strong></div><div><small>一緒に働く人</small><strong>${s.initial.staff+1} → ${s.staff+1}人</strong></div><div><small>手元資金</small><strong>${num(s.cash)}万円</strong></div></div><div style="margin-top:28px">${chart()}${chart('revenue','四半期売上 / 万円')}${chart('staff','従業者 / 人')}</div><details><summary>最終四半期の会計を見る</summary>${ledger()}</details></div><div><div class="section-heading" style="margin-top:0"><h2>この会社の、小さな歴史</h2><button class="text-button" data-do="history">すべての記録 →</button></div>${timeline(true)}</div></div><div class="result-actions"><button class="primary" data-do="new">別の会社をはじめる <span class="arrow">→</span></button><button class="text-button" data-do="replay">↻ 同じ条件でやり直す</button><button class="text-button" data-do="export">記録を書き出す ↓</button></div>${footer()}</main>`;}
function show(title,content){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-do="dismiss" aria-label="閉じる">×</button></div>${content}`;modal.showModal();}
function download(raw,name){const url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function data(){const c=s?.config||config;show('データと、この世界の約束',`<span class="assumption-label">全パラメータ：ゲーム上の仮置き</span><p>統計を背景に、一社ごとの違いを楽しむためのデモです。現段階では実測データをモデルへ採用していません。表示される結果は、現実の成功・廃業確率や経営判断を再現するものではありません。</p><p>売上は納品時に計上し、通常は55%を当期、残りを次期に回収。入金遅延時は当期回収予定も次期へ繰り越します。借入は利益に加えず、元本返済は費用に含めません。創業者の報酬も毎期支払います。</p><p>税・減価償却・貸倒・創業者の家計を省略。改善投資は一括費用。資金判定は四半期末の一括回収・支払後に行い、日次の資金不足は再現しません。借入の選択肢がある場合はゲーム上、必ず融資されます。</p><p>事務所の絵は共通のイメージ。手前の人物アイコンと表示人数が実際の体制に連動します。景気は継続しやすく、受注・採用・退職・入金遅延は状態をもとに抽選します。</p><details><summary>設定値・定義・今後の差し替え方</summary><p>モデル版：${MODEL}<br>データ版：${esc(c.version)}<br>単位：${esc(c.unit)}<br>対象：${esc(c.scope)}<br>母集団：${esc(c.population)}<br>出典URL・対象年度・取得日：未設定（実測未採用）<br>利用条件：${esc(c.licenseStatus)}</p><table class="ledger">${Object.entries(c.parameters).map(([k,v])=>`<tr><td>${k}</td><td>${v}</td></tr>`).join('')}</table><p>モデル処理と model-data.json を分離。対象・単位・出典・加工方法・利用条件を確認し、設定版を上げて新しい会社から反映します。進行中の記録には設定を保存し、後から黙って差し替えません。未設定値は0へ置換しません。</p></details><p>同じ初期条件・同じ選択列なら同じ結果になります。選択が変わると、その後の抽選順序も変わり得ます。「他の選択なら必ず助かった」という比較は行いません。</p><p><a href="../requirements.html" target="_blank" rel="noopener">整理したデモ要件・実装範囲を見る ↗</a></p>`);}
app.addEventListener('click',handle);modal.addEventListener('click',handle);modal.addEventListener('click',e=>{if(e.target===modal)modal.close();});
function handle(e){const c=e.target.closest('[data-choice]');if(c){selected=c.dataset.choice;render();document.querySelector(`[data-choice="${selected}"]`)?.focus({preventScroll:true});return;}const a=e.target.closest('[data-do]')?.dataset.do;if(!a)return;
if(a==='dismiss'){modal.close();return;}if(a==='data'){data();return;}if(a==='reroll'){const name=document.querySelector('#company').value;draft=create(newSeed(),name,config);welcome();return;}if(a==='start'){const name=document.querySelector('#company').value.trim()||'こもれびソフト';const start=()=>{s=create(draft.seed,name,config);selected='keep';brokenRaw='';persist();render();window.scrollTo(0,0);};if(brokenRaw){show('読み込めない記録が残っています',`<p>新しい会社を始めると保存枠が置き換わります。必要なら先に元の記録を書き出してください。</p><div class="modal-actions"><button data-do="export-broken" class="text-button">元の記録を書き出す</button><button class="primary" id="confirm-start">新しく始める</button></div>`);document.querySelector('#confirm-start').onclick=()=>{modal.close();start();};}else start();return;}
if(a==='next'){if(busy)return;busy=true;try{s=step(s,selected);selected='keep';persist();render();window.scrollTo({top:0,behavior:'smooth'});}catch(err){show('進行を止めました',`<p>${esc(err.message)}</p>`);}finally{busy=false;}return;}
if(a==='history'){show('会社の記録',`<p>${esc(s.name)} / ${s.q}四半期の歩み</p>${chart()}${timeline()}<button class="text-button" data-do="export">記録を書き出す ↓</button>`);return;}
if(a==='close-company'){show('この会社の経営を、ここで終える',`<p>今までの歩みを年表にまとめます。この記録で経営を再開することはできません。同じ創業条件での再プレイはできます。</p><div class="modal-actions"><button class="primary" data-do="confirm-close">経営を終えて、記録を読む</button><button class="text-button" data-do="dismiss">まだ続ける</button></div>`);return;}
if(a==='confirm-close'){s=close(s);persist();modal.close();render();window.scrollTo(0,0);return;}if(a==='export'||a==='export-broken'){download(a==='export'?JSON.stringify(s,null,2):brokenRaw,'company-life-record.json');return;}
if(a==='new'){draft=create(newSeed(),'こもれびソフト',config);s=null;selected='keep';welcome();window.scrollTo(0,0);return;}if(a==='replay'){s=create(s.seed,s.name,s.config);selected='keep';persist();render();window.scrollTo(0,0);}}
try{config=await(await fetch('model-data.json')).json();try{const raw=localStorage.getItem(KEY);if(raw){try{s=restore(raw);}catch(e){brokenRaw=raw;saveError=e.message;}}}catch(e){saveError='このブラウザでは保存を利用できません。';}render();}catch(e){app.innerHTML=`<main class="page"><h1>会社を開けませんでした</h1><p>${esc(e.message)}</p><button onclick="location.reload()">再読み込み</button></main>`;}
